// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, bytes memory data) public {
        vm.assume(target != address(c) && target != address(this) && target != address(0));
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(target, amount, data);
        assertTrue(address(target).balance == amount);
    }
}
